function renderWorkflow(wf) {
  const section = document.querySelector(`section[data-wf="${wf.id}"]`);
  section.innerHTML = `
    <div class="section-head"><span class="eyebrow">${esc(wf.code)}</span><h2>${esc(wf.title)}</h2><div class="goal">${esc(wf.goal)}</div><p>${esc(wf.thesis)}</p></div>
    <div class="toolbar">
      <div class="chips" role="group" aria-label="Filter stages">
        <button class="chip" data-filter="all" aria-pressed="true">All stages</button>
        <button class="chip" data-filter="d" aria-pressed="false">Deterministic only</button>
        <button class="chip" data-filter="s" aria-pressed="false">Semantic only</button>
        <button class="chip" data-filter="authority" aria-pressed="false">Gates and humans</button>
        <button class="chip" data-filter="proposed" aria-pressed="false">Proposed only</button>
        <button class="chip" data-filter="labels" aria-pressed="true">Schemas on edges</button>
      </div>
      <div class="stepper" aria-label="Step through stages"><button data-step="-1" aria-label="Previous stage">←</button><span class="pos">all</span><button data-step="1" aria-label="Next stage">→</button></div>
    </div>
    <div class="stage-wrap">
      <div class="diagram-caption"><span>Columns are stage order, not duration. The diagram scrolls sideways; select a stage or an edge to open it below.</span><span class="mono">${wf.stages.length} stages · ${wf.stages.filter(s => (s.status || 'implemented') === 'proposed').length} proposed</span></div>
      <div class="diagram" tabindex="0">${renderSvg(wf)}</div>
      <aside class="inspector" aria-live="polite"><p class="empty">Select a stage or an edge. Stages open their role, plugins, metrics and failure path; edges open the schema they carry.</p></aside>
    </div>
    <div class="stage-list">${wf.stages.map(s => `<details class="stage" id="${wf.id}-s${s.n}"><summary><span class="n">${s.n}</span><span><b>${esc(s.title)}</b> <span style="color:var(--ink-3)">· ${esc(s.actor)}</span></span><span class="badges"><span class="badge st-${s.status || 'implemented'}">${s.status || 'implemented'}</span><span class="badge t-${s.type}">${TYPE_LABEL[s.type]}</span></span></summary><div class="body"><p>${esc(s.desc)}</p><p><b>Emits</b> ${esc(s.outputs.join(', '))} · <b>Plugins</b> ${esc(s.plugins.existing.join(', '))}${s.plugins.new.length ? ` · <b>New</b> ${esc(s.plugins.new.join(', '))}` : ''}</p><p><b>Metrics</b> ${esc(s.metrics.join(', '))}${s.failure ? ` · <b>On failure</b> ${esc(s.failure)}` : ''}</p>${s.revised ? `<div class="rev"><b>Revised after the council (${esc(s.revised)}).</b> ${esc(s.note || '')}</div>` : ''}</div></details>`).join('')}</div>`;

  const inspector = section.querySelector('.inspector');
  const svg = section.querySelector('svg');
  const diagram = section.querySelector('.diagram');
  let step = 0; // 0 = all
  const maxCol = Math.max(...wf.stages.map(s => s.col));
  let filter = 'all';

  function applyState() {
    svg.querySelectorAll('.node').forEach(n => {
      const s = wf.stages.find(x => x.n === Number(n.dataset.stage));
      let visible = true;
      if (filter === 'd') visible = ['D', 'DS', 'GATE', 'STORE'].includes(s.type);
      if (filter === 's') visible = ['S', 'DS'].includes(s.type);
      if (filter === 'authority') visible = ['GATE', 'HUMAN'].includes(s.type);
      if (filter === 'proposed') visible = (s.status || 'implemented') !== 'implemented';
      if (step && s.col > step) visible = false;
      n.classList.toggle('dim', !visible);
    });
    svg.querySelectorAll('.edge').forEach(e => {
      const a = wf.stages.find(x => x.n === Number(e.dataset.from));
      const b = wf.stages.find(x => x.n === Number(e.dataset.to));
      const na = svg.querySelector(`.node[data-stage="${a.n}"]`), nb = svg.querySelector(`.node[data-stage="${b.n}"]`);
      const visible = !na.classList.contains('dim') && !nb.classList.contains('dim');
      e.classList.toggle('dim', !visible);
    });
    section.querySelector('.stepper .pos').textContent = step ? `stage ${step}/${maxCol}` : 'all';
  }
  section.querySelectorAll('.chip[data-filter]').forEach(btn => {
    btn.addEventListener('click', () => {
      const f = btn.dataset.filter;
      if (f === 'labels') { const on = btn.getAttribute('aria-pressed') !== 'true'; btn.setAttribute('aria-pressed', String(on)); diagram.classList.toggle('hide-labels', !on); return; }
      filter = f;
      section.querySelectorAll('.chip[data-filter]').forEach(b => { if (b.dataset.filter !== 'labels') b.setAttribute('aria-pressed', String(b.dataset.filter === f)); });
      applyState();
    });
  });
  section.querySelectorAll('.stepper button').forEach(btn => btn.addEventListener('click', () => {
    step = step + Number(btn.dataset.step);
    if (step < 0) step = maxCol; if (step > maxCol) step = 0;
    applyState();
    if (step) selectStage(wf.stages.find(s => s.col === step) || wf.stages[step - 1]);
  }));
  function clearSelection() { svg.querySelectorAll('.selected').forEach(x => x.classList.remove('selected')); }
  function selectStage(s) {
    clearSelection();
    svg.querySelector(`.node[data-stage="${s.n}"]`).classList.add('selected');
    inspector.innerHTML = stageCard(wf, s);
    bindSchemaLinks();
  }
  function selectEdge(el) {
    clearSelection(); el.classList.add('selected');
    const a = wf.stages.find(x => x.n === Number(el.dataset.from)), b = wf.stages.find(x => x.n === Number(el.dataset.to));
    const kind = el.classList.contains('feedback') ? 'Returned with the failure as its directive' : el.classList.contains('feed') ? 'Feeds a later consumer' : 'Forward hand-off';
    inspector.innerHTML = `<div class="badges"><span class="badge">${esc(wf.code)} · ${a.n} → ${b.n}</span><span class="badge">${esc(kind)}</span></div>` + schemaCard(el.dataset.schema) + `<p class="note">From <b>${esc(a.title)}</b> to <b>${esc(b.title)}</b>.</p>`;
  }
  function bindSchemaLinks() {
    inspector.querySelectorAll('.schema-link').forEach(b => b.addEventListener('click', () => { inspector.innerHTML = schemaCard(b.dataset.schema) + `<p class="note">Select a stage to return.</p>`; }));
  }
  svg.querySelectorAll('.node').forEach(n => {
    const act = () => selectStage(wf.stages.find(s => s.n === Number(n.dataset.stage)));
    n.addEventListener('click', act);
    n.addEventListener('keydown', (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); act(); } });
  });
  svg.querySelectorAll('.edge').forEach(el => {
    const act = () => selectEdge(el);
    el.addEventListener('click', act);
    el.addEventListener('keydown', (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); act(); } });
  });
  applyState();
}

